const DEFAULT_OPTIONS = {
    size: 24,
    strokeWidth: 2,
    className: '',
    title: '',
    decorative: false
};

function normalizeSvgSource(source) {
    return String(source);
}

function renderExternalSvg(source, config, classes, ariaHidden, title) {
    let normalized = normalizeSvgSource(source.trim());
    const match = normalized.match(/<svg\b([^>]*)>/i);
    if (!match) return '';
    const attrs = match[1] || '';
    const viewBoxMatch = attrs.match(/\bviewBox\s*=\s*(["'])([^"']+)\1/i);
    const viewBox = viewBoxMatch ? `"${viewBoxMatch[2]}"` : '"0 0 24 24"';
    let fill = attrs.match(/\bfill\s*=\s*(["'])(.*?)\1/i)?.[2] || '';
    let stroke = attrs.match(/\bstroke\s*=\s*(["'])(.*?)\1/i)?.[2] || '';
    if (fill && !/^(none|currentcolor|inherit|transparent)$/i.test(fill)) fill = 'currentColor';
    if (stroke && !/^(none|currentcolor|inherit|transparent)$/i.test(stroke)) stroke = 'currentColor';
    const paintAttrs = [
        fill ? `fill="${escapeXML(fill)}"` : '',
        stroke ? `stroke="${escapeXML(stroke)}"` : ''
    ].filter(Boolean).join(' ');
    normalized = normalized.replace(
        /<svg\b[^>]*>/i,
        `<svg class="${classes}" width="${escapeXML(config.size)}" height="${escapeXML(config.size)}" viewBox=${viewBox} ${paintAttrs} color="currentColor" ${ariaHidden} focusable="false">${title}`
    );
    return normalized;
}

export function icon(name, options = {}) {
    const config = { ...DEFAULT_OPTIONS, ...options };
    const content = ICONS[name];

    if (!content) {
        console.warn(`[Motoclube] Ícone não encontrado: ${name}`);
        return '';
    }

    const title = config.title ? `<title>${escapeXML(config.title)}</title>` : '';
    const ariaHidden = config.decorative || !config.title
        ? 'aria-hidden="true"'
        : `aria-label="${escapeXML(config.title)}"`;
    const classes = ['mc-icon', config.className].filter(Boolean).join(' ');
    const source = String(content).trim();

    if (source.startsWith('<svg')) {
        return renderExternalSvg(source, config, classes, ariaHidden, title);
    }

    return `
        <svg class="${classes}" width="${escapeXML(config.size)}" height="${escapeXML(config.size)}"
            viewBox="0 0 24 24" fill="none" stroke="currentColor"
            stroke-width="${escapeXML(config.strokeWidth)}" stroke-linecap="round" stroke-linejoin="round"
            ${ariaHidden} focusable="false">
            ${title}
            ${source}
        </svg>
    `.trim();
}

export function hydrateIcons(root = document) {
    if (!root || typeof root.querySelectorAll !== 'function') return 0;
    const nodes = [];
    if (root.matches?.('[data-icon]')) nodes.push(root);
    nodes.push(...root.querySelectorAll('[data-icon]'));
    let hydrated = 0;
    nodes.forEach(node => {
        if (node.dataset.iconHydrated === 'true') return;
        const name = node.dataset.icon;
        if (!name) return;
        const svg = icon(name, {
            size: node.dataset.iconSize || 24,
            className: node.className || '',
            title: node.getAttribute('aria-label') || '',
            decorative: !node.getAttribute('aria-label')
        });
        if (!svg) return;
        node.innerHTML = svg;
        node.dataset.iconHydrated = 'true';
        hydrated += 1;
    });
    return hydrated;
}

export function getIcon(name) { return ICONS[name] || ''; }
export function hasIcon(name) { return Object.prototype.hasOwnProperty.call(ICONS, name); }
export function iconNames() { return Object.keys(ICONS); }

export function registerIcon(name, svgContent) {
    if (typeof name !== 'string' || !name.trim()) throw new TypeError('O nome do ícone é obrigatório.');
    if (typeof svgContent !== 'string' || !svgContent.trim()) throw new TypeError('O conteúdo SVG é obrigatório.');
    ICONS[name] = svgContent;
}

function escapeXML(value) {
    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

export default { icon, getIcon, hasIcon, iconNames, registerIcon };